import Image from "next/image";

export default function Hero() {
  return (
    <section className="relative overflow-hidden bg-[#F8F4EC]">

      {/* Map texture */}
        <div
          className="absolute inset-0 opacity-40"
          style={{
            backgroundImage: "url('/images/map-texture.png')",
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />           
      <div className="relative z-10 max-w-6xl mx-auto px-4">

        <div className="flex flex-col items-center text-center pt-0">

          <Image
            src="/images/brand/fio-logo.png"
            alt="Figuring It Out"
            width={500}
            height={500}
            priority
                      />
          <h1 className="font-serif text-[72px] leading-none tracking-wide text-[#234531]">
            FIGURING IT OUT
          </h1>

          <div className="flex items-center">

            <div className="h-px w-20 bg-[#C89D4A]" />

            <div className="w-3 h-3 rotate-45 bg-[#C89D4A]" />

            <div className="h-px w-28 bg-[#C89D4A]" />

          </div>

          <h2 className="font-serif text-[54px] leading-tight text-[#234531]">
            Choosing to keep moving
          </h2>

          <p className="mt-0 text-[50px] italic text-[#C89D4A] font-serif">
            when life doesn't make sense.
          </p>

          <p className="mt-4 text-4xl font-serif text-[#333]">
            One philosophy. Two paths.
          </p>

          <p className="mt-8 max-w-3xl text-xl leading-9 text-[#444]">
            Figuring It Out™ is the lifelong practice of moving through
            uncertainty with curiosity, courage and hope—trusting that
            understanding and confidence grow with every step.
          </p>

          <button className="mt-12 rounded-md bg-[#234531] px-10 py-5 text-white uppercase tracking-[.2em] hover:bg-[#1a3326] transition">
            BEGIN YOUR JOURNEY ✦
          </button>

        </div>

      </div>
    </section>
  );
}